style.css:
@-moz-document domain("roblox.com") {
body, .content, .container-main, .updater-container, .vng-container {
        background-image: url("https://i.ytimg.com/vi/pnBv7SxWWMM/sddefault.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }
    
    /* Hace transparentes los contenedores principales para ver el fondo */
    .container-main, .sections-container, .light-theme, .dark-theme {
        background: transparent !important;
    }
}
